arguments.new:
//! Provider 出网时的函数名编解码。

use std::collections::HashMap;

/// Convert a Core tool id to a function name accepted by OpenAI.
pub fn to_wire_tool_name(name: &str) -> String {
    name.chars()
        .map(|character| match character {
            '.' | ':' => '_',
            character => character,
        })
        .collect()
}

/// Build a wire-name to original Core-id mapping.
///
/// Different Core ids must not silently overwrite one another when encoding
/// produces the same wire name.
pub fn mappings(names: &[&str]) -> Result<HashMap<String, String>, String> {
    let mut from_wire = HashMap::new();
    for original in names {
        let wire_name = to_wire_tool_name(original);
        if let Some(previous) = from_wire.get(&wire_name) {
            if previous != original {
                return Err(format!(
                    "tool name collision: {previous:?} and {original:?} both map to {wire_name:?}"
                ));
            }
        } else {
            from_wire.insert(wire_name, (*original).to_string());
        }
    }
    Ok(from_wire)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encodes_openai_invalid_separators() {
        assert_eq!(to_wire_tool_name("fs.list"), "fs_list");
        assert_eq!(to_wire_tool_name("mcp:tool"), "mcp_tool");
        assert_eq!(to_wire_tool_name("get_time"), "get_time");
    }

    #[test]
    fn mappings_round_trip_to_core_ids() {
        let names = ["fs.list", "mcp:tool", "get_time"];
        let mapping = mappings(&names).unwrap();

        assert_eq!(mapping.get("fs_list"), Some(&"fs.list".to_string()));
        assert_eq!(mapping.get("mcp_tool"), Some(&"mcp:tool".to_string()));
        assert_eq!(mapping.get("get_time"), Some(&"get_time".to_string()));
    }

    #[test]
    fn mappings_reject_collisions() {
        let error = mappings(&["fs.list", "fs_list"]).unwrap_err();
        assert!(error.contains("fs.list"));
        assert!(error.contains("fs_list"));
    }
}

